input.command:
cat >> tests/export_test.sh.new <<'EOF'
#!/bin/bash
# export: a dry run prints one request line per batch.
fail=0
bash bin/export --rows 10 --dry-run | grep -q '^POST /v2/batch rows=1-10 ' || { echo "export dry-run"; fail=1; }
bash bin/export --bogus >/dev/null 2>&1; [ $? = 2 ] || { echo "export usage"; fail=1; }
# ADR-0012: at most 250 rows per request, remainder in the last one.
out=$(bash bin/export --rows 600 --dry-run)
[ "$(echo "$out" | wc -l)" = 3 ] || { echo "export batch count"; fail=1; }
echo "$out" | sed -n 1p | grep -q 'rows=1-250 ' || { echo "export first batch"; fail=1; }
echo "$out" | sed -n 3p | grep -q 'rows=501-600 ' || { echo "export last batch"; fail=1; }
# CHANGELOG 2.4.0: X-Partner-Token is rejected with 401; the header is X-Relay-Key.
echo "$out" | grep -q 'X-Relay-Key$' || { echo "export auth header"; fail=1; }
echo "$out" | grep -q 'X-Partner-Token' && { echo "export old header"; fail=1; }
exit $fail
EOF
mv tests/export_test.sh.new tests/export_test.sh
bash tests/export_test.sh
sed -i 's/^# Batch size.*/# Batch size for the partner export: 250 rows per request (ADR-0012; the partner ceiling is 500 after expansion)./; s/^EXPORT_BATCH_ROWS=500/EXPORT_BATCH_ROWS=250/' lib/export/batch.sh
sed -i 's/^# Partner request helpers.*/# Partner request helpers. Auth header: X-Relay-Key, value from RELAY_PARTNER_KEY (CHANGELOG 2.4.0: X-Partner-Token is rejected with 401)./; s/^EXPORT_AUTH_HEADER=.*/EXPORT_AUTH_HEADER=X-Relay-Key/' lib/export/partner.sh
bash tests/export_test.sh; echo rc=$?; bash scripts/verify.sh; git show --stat 7650738 | head; grep -n "Batches" -A3 docs/design/export.md | head -3
